/** Maximum length for binding descriptions (characters). */
export const MAX_BINDING_DESCRIPTION_LENGTH = 200;
/** Helper to create a binding with type inference. */
export function binding(def) {
    return def;
}
/** Helper to create a named binding collection. */
export function bindings(def) {
    return def;
}
const BINDING_COMMAND_NAME_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
function validateBindingCommandName(kind, name) {
    if (BINDING_COMMAND_NAME_RE.test(name)) {
        return;
    }
    throw new Error(`${kind} name "${name}" must be lowercase alphanumeric with optional single hyphen separators`);
}
/**
 * Validate every binding collection and binding.
 */
export function validateBindings(collections) {
    for (const collection of collections) {
        validateBindingCommandName("Binding collection", collection.name);
        if (collection.description.length > MAX_BINDING_DESCRIPTION_LENGTH) {
            throw new Error(`Binding collection "${collection.name}" description is ${collection.description.length} characters, max is ${MAX_BINDING_DESCRIPTION_LENGTH}`);
        }
        for (const [bindingName, definition] of Object.entries(collection.bindings)) {
            validateBindingCommandName("Binding", bindingName);
            if (definition.description.length > MAX_BINDING_DESCRIPTION_LENGTH) {
                throw new Error(`Binding "${collection.name}/${bindingName}" description is ${definition.description.length} characters, max is ${MAX_BINDING_DESCRIPTION_LENGTH}`);
            }
        }
    }
}
